using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Threading;
using System.Windows.Forms;
class Setup : Form {
 const string Exe="War Thunder Scope Maker.exe";
 readonly string target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","WT Scope Maker");
 Button install=new Button(); Label note=new Label(); CheckBox launch=new CheckBox();
 Setup(){Text="WT Scope Maker — Setup 0.8.1";ClientSize=new Size(580,290);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.White;
 Controls.Add(new Label{Text="WT Scope Maker",Font=new Font("Segoe UI",22,FontStyle.Bold),AutoSize=true,Location=new Point(28,24)});
 note.SetBounds(30,82,520,100);note.Text="Установка / обновление 0.8.1 pre-alpha\nБез прав администратора. Настройки и проекты сохраняются.\n\n"+target;Controls.Add(note);
 launch.Text="Запустить после установки / Launch after setup";launch.Checked=true;launch.SetBounds(30,194,510,28);Controls.Add(launch);
 install.Text="Установить / обновить";install.SetBounds(330,237,220,36);install.BackColor=Color.FromArgb(82,105,235);install.ForeColor=Color.White;install.FlatStyle=FlatStyle.Flat;install.Click+=delegate{install.Enabled=false;try{Install(target);Shortcut(target);note.Text="Готово! Версия 0.8.1 установлена.\nDone! Version 0.8.1 installed.\n\n"+target;if(launch.Checked)System.Diagnostics.Process.Start(Path.Combine(target,Exe));install.Text="Закрыть / Close";install.Enabled=false;var close=new Button{Text="Закрыть / Close",Bounds=install.Bounds};close.Click+=delegate{Close();};Controls.Remove(install);Controls.Add(close);}catch(Exception ex){MessageBox.Show(this,"Закройте Scope Maker и повторите установку.\nClose Scope Maker and retry.\n\n"+ex.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Warning);install.Enabled=true;}};Controls.Add(install);}

 internal static void Install(string target){target=Path.GetFullPath(target);Directory.CreateDirectory(target);string stage=Path.Combine(target,".setup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);bool retainBackup=false;var changed=new List<string>();var backups=new Dictionary<string,string>();try{var names=new List<string>();using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){if(String.IsNullOrEmpty(entry.Name))continue;string relative=entry.FullName.Replace('/',Path.DirectorySeparatorChar);string destination=Path.GetFullPath(Path.Combine(target,relative));if(!destination.StartsWith(target+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Invalid archive path");if(String.Equals(relative,"settings.json",StringComparison.OrdinalIgnoreCase)||(relative.EndsWith(".wtsm",StringComparison.OrdinalIgnoreCase)&&File.Exists(destination)))continue;string prepared=Path.Combine(stage,"new",relative);Directory.CreateDirectory(Path.GetDirectoryName(prepared));entry.ExtractToFile(prepared);names.Add(relative);}}
 foreach(string name in names){string path=Path.Combine(target,name);if(File.Exists(path)){using(File.Open(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){}string backup=Path.Combine(stage,"old",name);Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Copy(path,backup);backups.Add(name,backup);}}
 try{foreach(string name in names){string path=Path.Combine(target,name);Directory.CreateDirectory(Path.GetDirectoryName(path));changed.Add(name);File.Copy(Path.Combine(stage,"new",name),path,true);}}catch{retainBackup=true;foreach(string name in changed){string path=Path.Combine(target,name);if(backups.ContainsKey(name))File.Copy(backups[name],path,true);else if(File.Exists(path))File.Delete(path);}retainBackup=false;throw;}
 }finally{if(!retainBackup)Directory.Delete(stage,true);}}
 static void Shortcut(string target){Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type);try{foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.Programs)}){object shortcut=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{Path.Combine(folder,"WT Scope Maker.lnk")});try{var t=shortcut.GetType();t.InvokeMember("TargetPath",BindingFlags.SetProperty,null,shortcut,new object[]{Path.Combine(target,Exe)});t.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,shortcut,new object[]{target});t.InvokeMember("Save",BindingFlags.InvokeMethod,null,shortcut,null);}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);}}}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
 [STAThread] static int Main(string[] args){bool owned;using(var mutex=new Mutex(true,"Local\\WTScopeMakerSetup",out owned)){if(!owned)return 2;try{if(args.Length==2&&args[0]=="--test-install"){Install(args[1]);return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Setup());return 0;}catch(Exception ex){if(args.Length==2)File.WriteAllText(args[1]+".error.txt",ex.ToString());return 1;}}}
}
